using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata retrieval: GetTypeInfo<T>()
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
// In .NET 9+ you can also use the generic extension if available,
// but the cast from the non-generic overload is the typical pattern.
Console.WriteLine($"Got typed info for: {personInfo.Type.Name}");

// 2) Probe without throwing: TryGetTypeInfo(Type, out JsonTypeInfo?)
bool found = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"TryGetTypeInfo(Person): found={found}, type={info?.Type.Name}");

bool notFound = options.TryGetTypeInfo(typeof(Stream), out JsonTypeInfo? missing);
Console.WriteLine($"TryGetTypeInfo(Stream): found={notFound}, info is null={missing is null}");

