using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Use a source-generated context so only known types are resolvable.
var options = new JsonSerializerOptions
{
    TypeInfoResolver = MyContext.Default
};

// 1) Strongly-typed metadata: GetTypeInfo<T>() — returns JsonTypeInfo<T> directly (.NET 9+)
JsonTypeInfo<Person> personInfo = MyContext.Default.Person;
Console.WriteLine($"Got typed JsonTypeInfo<{personInfo.Type.Name}>");

// Alternatively, from the options (returns non-generic, cast to typed):
var typed = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Via options.GetTypeInfo: {typed.Type.Name}");

// 2) Probe without throwing: TryGetTypeInfo (returns false if type is unknown)
bool found = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"\nTryGetTypeInfo(Person):  found={found}, type={info?.Type.Name}");

bool notFound = options.TryGetTypeInfo(typeof(DateTime), out JsonTypeInfo? missing);
Console.WriteLine($"TryGetTypeInfo(DateTime): found={notFound}, info is null={missing is null}");

// --- Types & context ---------------------------------------------------
public record Person(string Name, int Age);

[JsonSerializable(typeof(Person))]
public partial class MyContext : JsonSerializerContext;

